@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_M": 128, "BLOCK_N": 128, "BLOCK_K": 64}, num_warps=16, num_stages=2
        ),
    ],
    key=["SEQ_LEN", "HEAD_DIM"],
)
@triton.jit
def _qk_gemm_kernel(
    Q_ptr,
    K_ptr,
    S_ptr,
    stride_qb,
    stride_qm,
    stride_qd,
    stride_kb,
    stride_kn,
    stride_kd,
    stride_sb,
    stride_sm,
    stride_sn,
    SEQ_LEN,
    HEAD_DIM,
    scale,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
):
    pid_b = tl.program_id(0)
    pid_tile = tl.program_id(1)

    num_n = tl.cdiv(SEQ_LEN, BLOCK_N)
    pid_m = pid_tile // num_n
    pid_n = pid_tile % num_n

    q_base = Q_ptr + pid_b.to(tl.int64) * stride_qb
    k_base = K_ptr + pid_b.to(tl.int64) * stride_kb

    Q_bp = tl.make_block_ptr(
        base=q_base,
        shape=(SEQ_LEN, HEAD_DIM),
        strides=(stride_qm, stride_qd),
        offsets=(pid_m * BLOCK_M, 0),
        block_shape=(BLOCK_M, BLOCK_K),
        order=(1, 0),
    )
    KT_bp = tl.make_block_ptr(
        base=k_base,
        shape=(HEAD_DIM, SEQ_LEN),
        strides=(stride_kd, stride_kn),
        offsets=(0, pid_n * BLOCK_N),
        block_shape=(BLOCK_K, BLOCK_N),
        order=(1, 0),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for _ in range(0, HEAD_DIM, BLOCK_K):
        q = tl.load(Q_bp, boundary_check=(0, 1))
        k_t = tl.load(KT_bp, boundary_check=(0, 1))
        acc = tl.dot(q, k_t, acc)
        Q_bp = tl.advance(Q_bp, (0, BLOCK_K))
        KT_bp = tl.advance(KT_bp, (BLOCK_K, 0))

    acc = acc * scale

    s_base = S_ptr + pid_b.to(tl.int64) * stride_sb
    S_bp = tl.make_block_ptr(
        base=s_base,
        shape=(SEQ_LEN, SEQ_LEN),
        strides=(stride_sm, stride_sn),
        offsets=(pid_m * BLOCK_M, pid_n * BLOCK_N),
        block_shape=(BLOCK_M, BLOCK_N),
        order=(1, 0),
    )
    tl.store(S_bp, acc.to(S_ptr.dtype.element_ty), boundary_check=(0, 1))


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_M": 64, "BLOCK_K": 64, "BLOCK_N": 128}, num_warps=8, num_stages=3
        ),
    ],
    key=["SEQ_LEN", "HEAD_DIM"],
)
@triton.jit
def _fused_softmax_pv_kernel(
    S_ptr,
    V_ptr,
    O_ptr,
    stride_sb,
    stride_sm,
    stride_sn,
    stride_vb,
    stride_vn,
    stride_vd,
    stride_ob,
    stride_om,
    stride_od,
    SEQ_LEN,
    HEAD_DIM,
    BLOCK_M: tl.constexpr,
    BLOCK_K: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    pid_b = tl.program_id(0)
    pid_tile = tl.program_id(1)

    num_n = tl.cdiv(HEAD_DIM, BLOCK_N)
    pid_m = pid_tile // num_n
    pid_n = pid_tile % num_n

    s_base = S_ptr + pid_b.to(tl.int64) * stride_sb
    v_base = V_ptr + pid_b.to(tl.int64) * stride_vb
    off_m = pid_m * BLOCK_M

    LOG2E = 1.4426950408889634

    m_i = tl.full([BLOCK_M], float("-inf"), dtype=tl.float32)
    l_i = tl.zeros([BLOCK_M], dtype=tl.float32)
    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)

    for off_k in range(0, SEQ_LEN, BLOCK_K):
        S_bp = tl.make_block_ptr(
            base=s_base,
            shape=(SEQ_LEN, SEQ_LEN),
            strides=(stride_sm, stride_sn),
            offsets=(off_m, off_k),
            block_shape=(BLOCK_M, BLOCK_K),
            order=(1, 0),
        )
        s = tl.load(S_bp, boundary_check=(0, 1)).to(tl.float32)

        chunk_max = tl.max(s, axis=1)
        m_new = tl.maximum(m_i, chunk_max)
        alpha = tl.math.exp2((m_i - m_new) * LOG2E)
        exp_s = tl.math.exp2((s - m_new[:, None]) * LOG2E)
        chunk_sum = tl.sum(exp_s, axis=1)
        l_i = alpha * l_i + chunk_sum
        acc = acc * alpha[:, None]
        m_i = m_new

        V_bp = tl.make_block_ptr(
            base=v_base,
            shape=(SEQ_LEN, HEAD_DIM),
            strides=(stride_vn, stride_vd),
            offsets=(off_k, pid_n * BLOCK_N),
            block_shape=(BLOCK_K, BLOCK_N),
            order=(1, 0),
        )
        v = tl.load(V_bp, boundary_check=(0, 1))
        acc = tl.dot(exp_s.to(v.dtype), v, acc)

    acc = acc / l_i[:, None]

    o_base = O_ptr + pid_b.to(tl.int64) * stride_ob
    O_bp = tl.make_block_ptr(
        base=o_base,
        shape=(SEQ_LEN, HEAD_DIM),
        strides=(stride_om, stride_od),
        offsets=(off_m, pid_n * BLOCK_N),
        block_shape=(BLOCK_M, BLOCK_N),
        order=(1, 0),
    )
    tl.store(O_bp, acc.to(O_ptr.dtype.element_ty), boundary_check=(0, 1))


class Model(nn.Module):
    def __init__(self):
        super().__init__()
        self._s_buf = None
        self._o_buf = None

    def forward(self, Q, K, V):
        B, H, S, D = Q.shape
        scale = 1.0 / math.sqrt(D)

        device = Q.device

        Q = Q.reshape(B * H, S, D).contiguous()
        K = K.reshape(B * H, S, D).contiguous()
        V = V.reshape(B * H, S, D).contiguous()

        BH = B * H

        if (
            self._s_buf is None
            or self._s_buf.shape != (BH, S, S)
            or self._s_buf.device != device
        ):
            self._s_buf = torch.empty(BH, S, S, device=device, dtype=torch.float32)
        S_mat = self._s_buf

        grid1 = lambda META: (
            BH,
            triton.cdiv(S, META["BLOCK_M"]) * triton.cdiv(S, META["BLOCK_N"]),
        )
        _qk_gemm_kernel[grid1](
            Q,
            K,
            S_mat,
            Q.stride(0),
            Q.stride(1),
            Q.stride(2),
            K.stride(0),
            K.stride(1),
            K.stride(2),
            S_mat.stride(0),
            S_mat.stride(1),
            S_mat.stride(2),
            S,
            D,
            scale,
        )

        if (
            self._o_buf is None
            or self._o_buf.shape != (BH, S, D)
            or self._o_buf.device != device
            or self._o_buf.dtype != Q.dtype
        ):
            self._o_buf = torch.empty(BH, S, D, device=device, dtype=Q.dtype)
        O = self._o_buf

        grid2 = lambda META: (
            BH,
            triton.cdiv(S, META["BLOCK_M"]) * triton.cdiv(D, META["BLOCK_N"]),
        )
        _fused_softmax_pv_kernel[grid2](
            S_mat,
            V,
            O,
            S_mat.stride(0),
            S_mat.stride(1),
            S_mat.stride(2),
            V.stride(0),
            V.stride(1),
            V.stride(2),
            O.stride(0),
            O.stride(1),
            O.stride(2),
            S,
            D,
        )

        result = O.reshape(B, H, S, D)

        return result


